SELECT CASE WHEN s.sqft >= 15517 THEN 'high' WHEN s.sqft >= 6161 THEN 'mid' ELSE 'low' END AS sqft_bucket, MAX(o.discount) AS max_discount, MIN(o.amount) AS min_amount FROM orders o INNER JOIN customers c ON o.customer_id = c.id LEFT JOIN stores s ON s.id = o.store_id WHERE c.is_active = TRUE GROUP BY CASE WHEN s.sqft >= 15517 THEN 'high' WHEN s.sqft >= 6161 THEN 'mid' ELSE 'low' END HAVING min_amount > 1350;
